<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class SeoActivity extends Model {protected $fillable=['seo_campaign_id','seo_monthly_cycle_id','category','title','target_url','description','assigned_to','start_date','deadline','priority','status','work_notes','evidence_url','completed_at','reviewed_by','reviewed_at','review_feedback'];protected $casts=['start_date'=>'date','deadline'=>'date','completed_at'=>'datetime','reviewed_at'=>'datetime'];public function campaign(){return $this->belongsTo(SeoCampaign::class,'seo_campaign_id');}public function assignee(){return $this->belongsTo(User::class,'assigned_to');}}
